<template><CustomerWorkShell title="创建退款申请" :manager="manager" :domain-busy="financial.busy.value||reading" active="refunds"><template #recovery><CustomerWorkFinancialRecoveryPanel :operations="financial" /></template><template v-if="order"><view class="cw-card"><text class="cw-subtitle">订单 {{ order.order_id }}</text><text class="cw-scope">全站订单 · {{ order.store_id?'门店 '+order.store_id:order.supplier_id?'供应商 '+order.supplier_id:'平台' }} · 实付 ¥{{ order.pay_price }}</text><text class="cw-scope">先核对实际可退商品与金额，创建申请后另行确认资金退款。</text><text v-if="financial.order.value&&!financial.order.value.data.readiness.writes" class="cw-error">{{ customerFinancialNotice(financial.order.value.data.readiness.reason) }}</text></view><view v-if="financial.order.value" class="cw-card"><text class="cw-subtitle">退款商品范围</text><view class="cw-tabs"><button :class="{active:selectionMode==='remaining'}" :disabled="financial.busy.value||reading" @tap="chooseMode('remaining')">全部剩余可退商品</button><button :class="{active:selectionMode==='items'}" :disabled="financial.busy.value||reading" @tap="chooseMode('items')">按商品数量退款</button></view><view v-for="item in catalog" :key="item.cart_row_id" class="cw-cart" :data-refund-cart-row="item.cart_row_id"><image v-if="item.image" :src="item.image" class="cw-image" mode="aspectFill" /><view class="cw-stack cw-grow"><text>{{ item.title }}</text><text class="cw-muted">{{ item.sku }} · 当前可退 {{ item.max_num }} 件</text><text>本行可退金额 ¥{{ item.line_price }}</text><view v-if="selectionMode==='items'" class="cw-quantity"><checkbox :checked="!!quantities[item.cart_row_id]" :disabled="financial.busy.value||reading" @tap="toggle(item)" /><button :disabled="financial.busy.value||reading||(quantities[item.cart_row_id]||0)<=1" @tap="quantity(item,-1)">−</button><text>{{ quantities[item.cart_row_id]||0 }} 件</text><button :disabled="financial.busy.value||reading||(quantities[item.cart_row_id]||0)>=item.max_num" @tap="quantity(item,1)">＋</button></view></view></view><text v-if="!catalog.length" class="cw-scope">当前商品范围无法完整核对，请重新读取或人工核对。</text><button class="cw-full" :disabled="reading||financial.busy.value||!financial.order.value.data.readiness.quote" @tap="getQuote">{{ reading?'核对中…':'核对可退金额' }}</button></view><view v-if="quote" class="cw-card" data-financial-quote="current"><text class="cw-subtitle">已核对可退金额 ¥{{ quote.quoted_price }}</text><text class="cw-scope">{{ quote.items.length }} 行商品 · 退款时限 {{ quote.refund_time_days }} 天。修改商品范围或数量后须重新核对金额。</text><view class="cw-form-field"><text>本次申请退款金额（元）</text><input v-model="refundPrice" type="digit" maxlength="13" /></view><view class="cw-form-field"><text>退款原因</text><textarea v-model="reason" :maxlength="510" placeholder="填写 1 至 255 字的退款原因" /></view><button class="cw-full" :disabled="financial.busy.value||reading||!financial.order.value?.data.actions.refund_create.available" @tap="create">创建申请并核对资金退款</button></view><text v-if="message" class="cw-scope">{{ message }}</text><text v-if="error||financial.error.value" class="cw-error">{{ error||financial.error.value }}</text></template></CustomerWorkShell></template>
<script setup lang="ts">
import {ref} from 'vue';
import CustomerWorkShell from '@/components/customerWork/CustomerWorkShell.vue';
import CustomerWorkFinancialRecoveryPanel from '@/components/customerWork/CustomerWorkFinancialRecoveryPanel.vue';
import {useCustomerWork} from '@/composables/useCustomerWork';
import {useCustomerWorkFinancialOperations} from '@/composables/useCustomerWorkFinancialOperations';
import {isCustomerWorkOrderDetail} from '@/utils/customerWork';
import {financialAmount,financialCents,financialReason,financialNumber,customerWorkCanonicalJson,customerFinancialNotice,customerFinancialResultMessage} from '@/utils/customerWorkFinancial';
import type {CustomerWorkOrderDetail} from '@/types/customerWork';
import type {CustomerFinancialRefundQuote,CustomerFinancialQuoteItem} from '@/types/customerWorkFinancial';
const order=ref<CustomerWorkOrderDetail|null>(null),orderNo=ref(''),selectionMode=ref<'remaining'|'items'>('remaining'),catalog=ref<CustomerFinancialQuoteItem[]>([]),quantities=ref<Record<number,number>>({}),quote=ref<CustomerFinancialRefundQuote|null>(null),refundPrice=ref(''),reason=ref(''),reading=ref(false),error=ref(''),message=ref('');let readEpoch=0;
const manager=useCustomerWork({page:'refund',query(query){orderNo.value=query.orderId!;},clear(){readEpoch++;order.value=null;catalog.value=[];quantities.value={};quote.value=null;refundPrice.value='';reason.value='';selectionMode.value='remaining';reading.value=false;error.value='';message.value='';financial.clearDomain();},async load(controller){const valid=controller.fence(),no=orderNo.value,response=await controller.read(`orders/${encodeURIComponent(no)}`,isCustomerWorkOrderDetail);if(!valid())return;if(response.data.order_id!==no)throw Error('退款原订单编号不匹配');order.value=response.data;const basis=await financial.loadOrder(response.data.id,no);if(!valid())return;if(basis.uid!==response.data.uid||basis.store_id!==response.data.store_id||basis.supplier_id!==response.data.supplier_id)throw Error('退款原订单财务实体归属不匹配');await financial.checkRelevant(basis.payment_order_id);if(!valid())return;if(basis.readiness.quote&&basis.actions.refund_create.available)await getQuote();}}),financial=useCustomerWorkFinancialOperations(manager);
function clearQuote(){readEpoch++;quote.value=null;refundPrice.value='';error.value='';message.value='';}
function chooseMode(value:'remaining'|'items'){if(financial.busy.value||reading.value||selectionMode.value===value)return;selectionMode.value=value;clearQuote();}
function toggle(item:CustomerFinancialQuoteItem){if(financial.busy.value||reading.value)return;clearQuote();quantities.value[item.cart_row_id]=quantities.value[item.cart_row_id]?0:item.max_num;}
function quantity(item:CustomerFinancialQuoteItem,delta:number){if(financial.busy.value||reading.value)return;const next=(quantities.value[item.cart_row_id]||0)+delta;if(!Number.isInteger(next)||next<1||next>item.max_num)return;clearQuote();quantities.value[item.cart_row_id]=next;}
function selected(){return selectionMode.value==='remaining'?[]:catalog.value.filter(item=>(quantities.value[item.cart_row_id]||0)>0).map(item=>({cart_row_id:item.cart_row_id,cart_num:quantities.value[item.cart_row_id]!})).sort((a,b)=>a.cart_row_id-b.cart_row_id);}
async function getQuote(){if(reading.value||financial.busy.value||!financial.order.value)return;const valid=manager.fence(),version=++readEpoch;quote.value=null;refundPrice.value='';reading.value=true;error.value='';try{const items=selected();if(selectionMode.value==='items'&&!items.length)throw Error('请选择退款商品及数量');const value=await financial.quote(selectionMode.value,items);if(!valid()||version!==readEpoch)return;if(value.mode==='remaining'){catalog.value=JSON.parse(customerWorkCanonicalJson(value.items));quantities.value={};}quote.value=value;refundPrice.value=value.quoted_price;}catch(failure){if(valid()&&version===readEpoch)error.value=failure instanceof Error?customerFinancialNotice(failure.message):'当前退款报价需核对';}finally{if(valid()&&version===readEpoch)reading.value=false;}}
async function create(){const value=quote.value,basis=financial.order.value?.data;if(financial.busy.value||reading.value||!value||!basis)return;const valid=manager.fence();error.value='';try{const refund_price=financialAmount(refundPrice.value);if(financialCents(refund_price)>financialCents(value.quoted_price))throw Error('退款申请金额不能超过本次商品报价');const why=financialReason(reason.value),items=selected();if(value.mode!==selectionMode.value||value.order_id!==basis.order_id||value.order_revision!==basis.order_revision||value.financial_revision!==basis.financial_revision)throw Error('商品范围或退款报价已变化，请重新核对');if(value.mode==='items'&&(value.items.length!==items.length||value.items.some(item=>!items.some(row=>row.cart_row_id===item.cart_row_id&&row.cart_num===item.cart_num))))throw Error('商品数量已变化，请重新核对');const result=await financial.submit('refund_create',basis,{mode:value.mode,items,quoted_price:value.quoted_price,refund_price,quote_fingerprint:value.quote_fingerprint,reason:why});if(!valid()||!result?.receipt)return;message.value=customerFinancialResultMessage(result);if(result.receipt.outcome==='refund-created'){const no=result.receipt.evidence.refund_no;if(!financialNumber(no))throw Error('新退款申请编号暂不可核对，请查询原操作');manager.go('refundDetail',{refundOrderId:no});}}catch(failure){if(valid())error.value=failure instanceof Error?customerFinancialNotice(failure.message):'退款申请内容需核对';}}
</script>
